/**
 * Ensures that all required jobs (and their transitive dependencies) are present in the jobs array.
 * Uses breadth-first traversal to collect all required jobs.
 */
export function ensureRequiredJobs(jobs: JobsOrHub[]): JobsOrHub[] {
  const results: JobsOrHub[] = [];
  const queue = [...jobs]; // Create a copy to avoid mutating input
  while (queue.length > 0) {
    const job = queue.shift();
    if (job) {
      if (results.find((r) => r.id === job.id)) {
        continue;
      }
      results.push(job);
      queue.push(...job.requires);
    }
  }
  return results;
}
```

</details>

